{"code": "def revcomp(s):
    tbl = str.maketrans("ACGT", "TGCA")
    return s.translate(tbl)[::-1]

seq = "".join(open("region.fasta").read().split("\n")[1:]).upper()

def find_orfs(s):
    """Return ORFs (frame 1) as (start_0based, end, strand) with ATG start."""
    orfs = []
    n = len(s)
    for frame in range(3):
        i = frame
        while i < n - 2:
            if s[i:i+3] == "ATG":
                # extend to next in-frame stop or sequence end
                stop = None
                for j in range(i + 3, n - 2, 3):
                    if s[j:j+3] in ("TAA", "TAG", "TGA"):
                        stop = j
                        break
                else:
                    stop = None
                if stop is not None and stop + 3 - i >= 180:  # >=60 aa
                    orfs.append((i, stop + 3 - i, "+", frame + 1))
            i += 3
    for frame in range(3):
        i = frame
        while i < n - 2:
            if s[i:i+3] == "CAT":
                rc = revcomp(s)
                orfs_ = find_orfs_plus(rc)
                break
            i += 3
    return orfs

def find_orfs_plus(s):
    return find_orfs(s)

# Simpler: just do all six frames generically
def orfs_all(s):
    res = []
    for strand, seqv in [("+", s), ("-", revcomp(s))]:
        n = len(seqv)
        for frame in range(3):
            i = frame
            while i < n - 2:
                if seqv[i:i+3] == "ATG":
                    stop = None
                    for j in range(i + 3, n - 2, 3):
                        if seqv[j:j+3] in ("TAA","TAG","TGA"):
                            stop = j
                            break
                    else:
                        stop = None
                    if stop is not None and stop + 3 - i >= 180:
                        res.append((strand, frame+1, i, i+stop+3, (stop+3-i)//3))
                i += 3
    return res

all_o = orfs_all(seq)
print("All ORFs >=60aa (strand, frame, start_in_strand_0based, end, length_aa):")
for o in sorted(all_o, key=lambda x: -x[4]):
    print(o)
