seq = "".join(open("region.fasta").read().split("\n")[1:]).upper()
n = len(seq)

# Global position mapping for minus strand: seq[pos] = revcomp index n-1-pos
res = []
for strand, sv in [("+", seq), ("-", revcomp(seq))]:
    for frame in range(3):
        i = frame
        while i < n - 2:
            if sv[i:i+3] == "ATG":
                for j in range(i+3, n-2, 3):
                    if sv[j:j+3] in ("TAA","TAG","TGA"):
                        j += 3
                        break
                else:
                    j = n - ((n - i) % 3)
                L = j - i
                if L >= 180:
                    if strand == "+":
                        gstart, gend = i+1, j          # 1-based inclusive
                    else:
                        gstart, gend = n - j + 1, n - i  # 1-based on plus strand
                    res.append((strand, frame+1, gstart, gend, L//3 - (1 if sv[j-1:j] else 0)))
            i += 3

res = [tuple(list(r)[:-1]) for r in res]
for r in sorted(res, key=lambda x: -(x[4]-1) if False else x[0]):
    pass
print("ORFs >=60 aa (strand, frame, gstart, gend, nt_len):")
