# --- DNA feature checks ---
# CpG density ( CpG islands ~ observed/expected >> 1 )
obs = seq.count("CG")
exp = (seq.count("C") * seq.count("G") / len(seq))
print("CpG count:", obs, "| expected:", round(exp,1), "| obs/exp:", round(obs/exp,2))
# GC does vary within the big ORF (55-61% in nt 1400-1900)
# Codon usage / G+C at third positions
from collections import Counter
codons = [seq[i:i+3] for i in range(1160, 2174, 3) if seq[i:i+3] not in ("TAA","TAG","TGA")]
thirds = [c[2] for c in codons]
print("Third-position GC%% in ORF: %.1f%%" % (100*sum(1 for t in thirds if t in "GC")/len(thirds)))
print("Top codons:", Counter(codons).most_common(8))

# Homopolymer runs
import re
for b in "ACGT":
    for m in re.finditer(b+"{%d,}" % 8, seq):
        print("Homopolymer", b, m.start()+1, "-", m.end(), "len", len(m.group()))

# Perfect direct repeats >= 15 bp
found = set()
for L in range(20, 14, -1):
    for i in range(len(seq)-L):
        k = seq[i:i+L]
        for j in range(i+L, len(seq)-L+1):
            if seq[j:j+L] == k:
                key = (k, j-i)
                if key not in found:
                    found.add(key)
                    print("Direct repeat", L, "bp at", i+1, "&", j+1, ":", k if L<=24 else "...")
        break
    if found:
        break

# Palindromic (inverted repeats) >= 12 bp stem
hits = []
for L in range(14, 11, -1):
    for i in range(len(seq)-L):
        s = seq[i:i+L]
        if s == s.translate(str.maketrans("ACGT","TGCA"))[::-1]:
            hits.append((i+1, L, s))
    if hits:
        break
print("Perfect palindromes (L, pos, seq):", sorted(set(hits), key=lambda x:x[0])[:10])
